    assessmentTools: { rubric: ['الترتيب', 'دور كل مرحلة', 'معنى «لم يكن… قد… بعدُ»', 'ضبط اسم «يكن» وخبر «أصبح»'], exitTicket: ['اكتب جملة فيها «لم يكن… قد… بعدُ» وجملة فيها «أصبح» عن مدينتك، واضبط الخبر.'] },
