    assessmentTools: { rubric: ['تدفّق النظام', 'الترتيب', 'ظلّ / ساعد على / صار / التمييز', 'النتيجتان المتقابلتان'], exitTicket: ['اكتب جملة فيها «ظلّ + مضارع» وجملة فيها «صار… بينما ازداد…» عن مدينتك أو مدرستك.'] },
